@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;1,500;1,600&display=swap');
:root{color-scheme:dark;--cream:#f3f0e5;--muted:rgba(243,240,229,.62);--line:rgba(243,240,229,.22);--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',serif}
*{box-sizing:border-box}html,body,#game{width:100%;height:100%;margin:0;overflow:hidden}body{background:#a9b5a5;color:var(--cream);font-family:var(--sans);user-select:none}#scene{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}.film-grain,.vignette{position:absolute;inset:0;pointer-events:none}.film-grain{opacity:.13;mix-blend-mode:soft-light;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.vignette{background:radial-gradient(ellipse at 52% 42%,transparent 34%,rgba(18,26,23,.16) 100%);transition:background .8s}.hud{position:absolute;inset:0;padding:30px 42px;pointer-events:none}.topline{display:flex;justify-content:space-between;align-items:center;font:10px var(--mono);letter-spacing:.13em}.brand{display:flex;gap:10px;align-items:center}.brand-dot{width:7px;height:7px;border-radius:100%;background:#e8e3c9;box-shadow:0 0 12px #fff8}.world-clock{display:flex;gap:10px;align-items:center;color:rgba(255,255,255,.82);letter-spacing:.05em}.world-clock #weather-icon{font-size:15px}.clock-divider{opacity:.35}.location{position:absolute;top:17%;left:42px;text-shadow:0 2px 18px #36433c44}.eyebrow{font:9px var(--mono);letter-spacing:.18em;color:rgba(255,255,255,.72)}.location h1{font:500 clamp(31px,4vw,48px) var(--serif);margin:9px 0 5px;letter-spacing:-.03em}.location p{font-size:12px;color:rgba(255,255,255,.72);margin:0;letter-spacing:.025em}.crosshair{position:absolute;left:50%;top:50%;width:14px;height:14px;transform:translate(-50%,-50%);opacity:.7}.crosshair i{position:absolute;background:rgba(255,255,255,.72)}.crosshair i:first-child{width:1px;height:12px;left:6.5px;top:1px}.crosshair i:last-child{height:1px;width:12px;top:6.5px;left:1px}.bottom-left{position:absolute;left:42px;bottom:32px;display:flex;align-items:flex-end;gap:30px}.compass{position:relative;width:45px;height:45px;border:1px solid rgba(255,255,255,.34);border-radius:50%;display:grid;place-items:center}.compass-n{position:absolute;top:3px;font:7px var(--mono);opacity:.72}.compass-tick{position:absolute;top:-2px;left:21px;width:1px;height:6px;background:#fff}.compass #compass-arrow{font-size:10px;transform:rotate(0);transition:transform .15s}.compass-degrees{position:absolute;bottom:-17px;font:8px var(--mono);letter-spacing:.05em;opacity:.72}.coordinates{display:grid;gap:4px;padding-bottom:1px;font:8px var(--mono);letter-spacing:.12em;color:rgba(255,255,255,.56)}.coordinates b{font-weight:400;color:#fff;font-size:10px}.bottom-right{position:absolute;right:42px;bottom:34px;width:176px}.sanity-top{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.14em}.sanity-top b{font-weight:400}.meter{height:2px;background:rgba(255,255,255,.3);margin:9px 0 7px;position:relative;overflow:hidden}.meter-fill{height:100%;width:86%;background:#f4ead1;transition:width .5s,background .5s;box-shadow:0 0 8px #fff9}.meter-glint{position:absolute;right:0;top:0;width:25%;height:100%;background:linear-gradient(90deg,transparent,#fff8)}.sanity-caption{font:9px var(--serif);font-style:italic;color:rgba(255,255,255,.78)}.center-message{position:absolute;left:50%;top:59%;transform:translate(-50%,0);font:11px var(--serif);font-style:italic;letter-spacing:.05em;text-shadow:0 1px 5px #223}.interaction{position:absolute;left:50%;bottom:16%;transform:translateX(-50%);display:flex;gap:10px;align-items:center;font:10px var(--mono);letter-spacing:.06em;text-shadow:0 1px 8px #223}.keycap{border:1px solid #fff9;padding:5px 8px;background:#19221b55}.toast{position:absolute;top:75%;left:50%;transform:translate(-50%,10px);font:10px var(--mono);letter-spacing:.1em;opacity:0;transition:.3s;text-shadow:0 1px 8px #222}.toast.show{opacity:1;transform:translate(-50%,0)}.wind-lines{position:absolute;inset:0;overflow:hidden;opacity:0;transition:opacity 1s}.wind-lines span{position:absolute;height:1px;width:80px;background:linear-gradient(90deg,transparent,#fff8,transparent);animation:windpass 1.8s linear infinite}@keyframes windpass{from{transform:translateX(-100vw)}to{transform:translateX(100vw)}}.screen{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(18,27,25,.66),rgba(22,31,27,.2) 72%,rgba(20,29,25,.06));backdrop-filter:blur(1px);transition:opacity .55s}.screen[hidden],.hud[hidden],.mobile-controls[hidden],.loading[hidden]{display:none}.screen-card{width:min(440px,calc(100% - 48px));margin-left:clamp(0px,36vw,500px);margin-top:0;text-shadow:0 2px 18px #101a16}.kicker{font:9px var(--mono);letter-spacing:.2em;color:rgba(255,255,255,.65);margin:0 0 20px}.screen h2{font:500 clamp(56px,8vw,88px)/.93 var(--serif);letter-spacing:-.065em;margin:0 0 24px}.screen h2 em{font-weight:500}.intro{font-size:13px;line-height:1.75;color:rgba(255,255,255,.77);max-width:365px;margin:0 0 27px}.screen button{width:236px;height:46px;padding:0 14px 0 17px;border:1px solid rgba(255,255,255,.68);color:#f4f0e6;background:rgba(235,231,211,.13);display:flex;align-items:center;justify-content:space-between;font:10px var(--mono);letter-spacing:.08em;cursor:pointer;transition:background .2s,color .2s,transform .2s}.screen button:hover{background:#f1eddf;color:#334137;transform:translateY(-2px)}.button-arrow{font-size:15px}.control-note{max-width:480px;margin-top:27px;font:8px var(--mono);line-height:2;color:rgba(255,255,255,.62);letter-spacing:.06em}.control-note span{color:#fff}.control-note i{font-style:normal;padding:0 5px;opacity:.4}.small-note{font:italic 11px var(--serif);color:rgba(255,255,255,.52);margin-top:17px}.edition{position:absolute;right:40px;bottom:33px;text-align:right;font:8px/1.8 var(--mono);letter-spacing:.16em;color:rgba(255,255,255,.65)}.pause-screen{background:rgba(17,26,23,.28);backdrop-filter:blur(5px)}.pause-card{margin-left:0}.pause-card h2{font-size:68px}.quiet-button{height:32px!important;width:auto!important;padding:0!important;border:0!important;background:none!important;opacity:.65;font-size:9px!important}.quiet-button:hover{background:none!important;color:#fff!important;opacity:1}.loading{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);font:9px var(--mono);letter-spacing:.18em;color:rgba(255,255,255,.78);display:flex;gap:10px;align-items:center}.loading-mark{font-size:17px;animation:rotate 1.5s linear infinite}@keyframes rotate{to{transform:rotate(360deg)}}.mobile-controls{position:absolute;inset:0;pointer-events:none}.move-pad{position:absolute;left:20px;bottom:22px;display:grid;gap:4px;pointer-events:auto}.move-pad>button{margin:auto}.move-pad div{display:flex;gap:4px}.mobile-controls button{border:1px solid #fff8;background:#18251e55;color:#fff;width:42px;height:42px;border-radius:50%;font:17px var(--mono);backdrop-filter:blur(3px);touch-action:none}.look-hint{position:absolute;right:78px;bottom:30px;width:auto!important;height:32px!important;border-radius:2px!important;padding:0 10px;font:8px var(--mono)!important;letter-spacing:.1em}.mobile-action{position:absolute;right:20px;bottom:22px;pointer-events:auto}.sanity-low .vignette{background:radial-gradient(ellipse at 52% 42%,transparent 9%,rgba(12,17,27,.68) 100%)}.sanity-low .film-grain{opacity:.25}.sanity-critical .location{filter:blur(.5px)}
@media(max-width:700px){.hud{padding:18px 18px}.topline{font-size:8px}.world-clock{gap:6px}.location{left:18px;top:14%}.location h1{font-size:34px}.location p{font-size:10px}.bottom-left{left:18px;bottom:92px;gap:23px}.bottom-right{right:18px;bottom:92px;width:140px}.sanity-caption{font-size:8px}.screen{background:linear-gradient(90deg,rgba(18,27,25,.72),rgba(22,31,27,.3))}.screen-card{margin:0 0 0 0;width:calc(100% - 48px);align-self:center}.screen h2{font-size:66px}.intro{font-size:12px;max-width:330px}.edition{right:18px;bottom:17px;font-size:7px}.control-note{font-size:7px;max-width:350px}.control-note span{white-space:nowrap}.pause-card h2{font-size:61px}.interaction{bottom:25%}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

const canvas = document.querySelector('#scene');
const loading = document.querySelector('#loading');
const startScreen = document.querySelector('#start-screen');
const pauseScreen = document.querySelector('#pause-screen');
const hud = document.querySelector('#hud');
const mobileControls = document.querySelector('#mobile-controls');
const isTouch = matchMedia('(pointer:coarse)').matches;
const renderer = new THREE.WebGLRenderer({canvas, antialias: true, powerPreference: 'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;

const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9b9b1');
scene.fog = new THREE.FogExp2('#a9b9b1', 0.0043);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, .08, 700);
const player = new THREE.Group();
player.position.set(0, 0, 14);
scene.add(player);
player.add(camera);
camera.position.set(0, 1.65, 0);
let yaw = 0, pitch = 0, running = false, started = false, paused = false;
let time = 0, fpsElapsed = 0, fpsFrames = 0, sanity = 86, clockTime = 14.45;
const keys = Object.create(null);
const velocity = new THREE.Vector3();
const forward = new THREE.Vector3(), right = new THREE.Vector3(), move = new THREE.Vector3();
const colliders = [], pointsOfInterest = [];
const clock = new THREE.Clock();
const clamp = THREE.MathUtils.clamp;
const mix = THREE.MathUtils.lerp;
const rand = (a,b) => a + Math.random()*(b-a);
const smooth = (a,b,x) => {const t=clamp((x-a)/(b-a),0,1); return t*t*(3-2*t)};

scene.add(new THREE.HemisphereLight('#f0ead4','#566650',1.45));
const sun = new THREE.DirectionalLight('#fff0ce',2.45);
sun.position.set(-110,170,75); scene.add(sun);
const fill = new THREE.DirectionalLight('#a9c5d0',.38); fill.position.set(100,30,-100); scene.add(fill);

function terrainHeight(x,z){return Math.sin(x*.018+z*.007)*.62+Math.sin(z*.014-x*.011)*.5+Math.sin(x*.042+z*.033)*.16;}
function makeTerrain(){
  const size=1100, seg=180, geo=new THREE.PlaneGeometry(size,size,seg,seg); geo.rotateX(-Math.PI/2);
  const pos=geo.attributes.position, colors=[];
  for(let i=0;i<pos.count;i++){
    const x=pos.getX(i), z=pos.getZ(i), h=terrainHeight(x,z); pos.setY(i,h);
    const n=(Math.sin(x*.045+z*.024)*Math.sin(z*.052-x*.017)+1)*.5;
    const c=new THREE.Color().setRGB(.29+n*.045,.365+n*.055,.245+n*.034); colors.push(c.r,c.g,c.b);
  }
  geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3)); geo.computeVertexNormals();
  const mat=new THREE.MeshStandardMaterial({vertexColors:true,roughness:.96,metalness:0});
  mat.onBeforeCompile=(shader)=>{
    shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 vWorldPos;');
    shader.vertexShader=shader.vertexShader.replace('#include <worldpos_vertex>','#include <worldpos_vertex>\nvWorldPos=(modelMatrix*vec4(transformed,1.0)).xyz;');
    shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vWorldPos;\nfloat hash21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}');
    shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat grain=hash21(floor(vWorldPos.xz*1.6)); diffuseColor.rgb*=0.91+grain*0.16; float streak=sin(vWorldPos.x*0.38+vWorldPos.z*0.26)*0.012; diffuseColor.rgb+=streak;');
  };
  const ground=new THREE.Mesh(geo,mat); ground.position.y=-.12; ground.receiveShadow=false; scene.add(ground);
}
makeTerrain();

// A very small animated sky veil: layered fog is rendered with Three's efficient standard pipeline.
const skyGeo=new THREE.SphereGeometry(600,24,16);
const skyMat=new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:{uTime:{value:0}},vertexShader:`varying vec3 vP; void main(){vP=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,fragmentShader:`varying vec3 vP; uniform float uTime; void main(){float h=normalize(vP).y; float band=smoothstep(-.4,.75,h); vec3 low=vec3(.69,.75,.70); vec3 high=vec3(.53,.65,.68); float cloud=sin(vP.x*.012+uTime*.006)*sin(vP.z*.009-uTime*.004)*.025; gl_FragColor=vec4(mix(low,high,band)+cloud,1.0);}`});
const sky=new THREE.Mesh(skyGeo,skyMat); scene.add(sky);

// Wind-bent grass: one lightweight instanced mesh, animated in the vertex shader.
function makeGrass(){
  const blade=new THREE.BufferGeometry();
  blade.setAttribute('position',new THREE.Float32BufferAttribute([-.045,0,0,.045,0,0,-.025,.34,0,.025,.34,0,0,.68,0],3));
  blade.setIndex([0,2,1,1,2,3,2,4,3]); blade.computeVertexNormals();
  const count=6300, offsets=new Float32Array(count*3), scale=new Float32Array(count), tint=new Float32Array(count);
  for(let i=0;i<count;i++){const x=rand(-410,410),z=rand(-410,410); offsets[i*3]=x; offsets[i*3+1]=terrainHeight(x,z)-.06; offsets[i*3+2]=z; scale[i]=rand(.55,1.65); tint[i]=rand(.78,1.18);}
  const geo=new THREE.InstancedBufferGeometry(); geo.index=blade.index; geo.setAttribute('position',blade.attributes.position); geo.setAttribute('normal',blade.attributes.normal); geo.setAttribute('offset',new THREE.InstancedBufferAttribute(offsets,3)); geo.setAttribute('bladeScale',new THREE.InstancedBufferAttribute(scale,1)); geo.setAttribute('bladeTint',new THREE.InstancedBufferAttribute(tint,1)); geo.instanceCount=count;
  const material=new THREE.ShaderMaterial({uniforms:{uTime:{value:0},uWind:{value:0.65}},vertexShader:`attribute vec3 offset; attribute float bladeScale; attribute float bladeTint; uniform float uTime; uniform float uWind; varying float vTint; varying float vHeight; void main(){vec3 p=position; float h=position.y; float phase=offset.x*.037+offset.z*.029; float sway=sin(uTime*1.22+phase)*uWind; p.x+=sway*h*h*.22; p.z+=cos(uTime*.83+phase*1.7)*uWind*h*h*.10; p*=bladeScale; vec3 world=offset+p; vTint=bladeTint; vHeight=h; gl_Position=projectionMatrix*viewMatrix*vec4(world,1.0);}`,fragmentShader:`varying float vTint; varying float vHeight; void main(){vec3 base=mix(vec3(.21,.30,.15),vec3(.59,.62,.34),clamp(vHeight*1.45,0.0,1.0))*vTint; gl_FragColor=vec4(base,1.0);}`,side:THREE.DoubleSide});
  const grass=new THREE.Mesh(geo,material); grass.frustumCulled=false; scene.add(grass); return material;
}
const grassMaterial=makeGrass();

const mat=(color,roughness=.8,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const materials={wood:mat('#776e57'),pale:mat('#c5b99c'),blue:mat('#788f91'),dark:mat('#424b43'),gold:mat('#c4a66f'),grass:mat('#8d9163'),glass:new THREE.MeshStandardMaterial({color:'#b8d1c9',roughness:.28,metalness:.1,transparent:true,opacity:.43}),stone:mat('#898979')};
function box(parent,x,y,z,w,h,d,material,rotation=0){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);mesh.position.set(x,y,z);mesh.rotation.y=rotation;parent.add(mesh);return mesh;}
function cylinder(parent,x,y,z,rt,rb,h,material,segments=8){const mesh=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),material);mesh.position.set(x,y,z);parent.add(mesh);return mesh;}
function addCollider(x,z,r){colliders.push({x,z,r});}

function makeBirch(x,z,s=1){
  const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);scene.add(g);
  cylinder(g,0,2.1*s,0,.20*s,.31*s,4.2*s,mat('#d0c8ac'),7);
  for(let i=0;i<3;i++){const a=i*2.1+rand(-.4,.4);const b=cylinder(g,Math.cos(a)*.5*s,3.8*s,Math.sin(a)*.5*s,.1*s,.16*s,2.7*s,mat('#c8bea3'),6);b.rotation.z=Math.cos(a)*.34;b.rotation.x=Math.sin(a)*.3;}
  for(let i=0;i<7;i++){const a=rand(0,Math.PI*2),r=rand(.3,1.45)*s;const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(rand(.55,.95)*s,1),mat(i%2?'#687a61':'#78836a'));crown.position.set(Math.cos(a)*r,rand(4.7,6.1)*s,Math.sin(a)*r);crown.scale.set(1,rand(.65,1.2),1);g.add(crown);}
  addCollider(x,z,.6*s);
}
function makePines(){for(let i=0;i<155;i++){let x,z;if(Math.random()<.54){x=rand(-200,200);z=rand(-245,245);}else{x=rand(-360,360);z=rand(-360,360);}if(Math.hypot(x,z)<25)continue;const s=rand(.68,1.55);if(Math.random()<.36)makeBirch(x,z,s);else{const y=terrainHeight(x,z);cylinder(scene,x,y+1.6*s,z,.06*s,.18*s,3.2*s,materials.wood,6);for(let j=0;j<3;j++){const cone=new THREE.Mesh(new THREE.ConeGeometry((1.45-j*.27)*s,(2.3-j*.17)*s,7),mat(j===1?'#596d59':'#65755e'));cone.position.set(x,y+(2.2+j*1.08)*s,z);scene.add(cone);}addCollider(x,z,.48*s);}}}
makePines();

function makeArch(x,z){
  const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);
  box(g,-3,3,0,.65,6,.72,materials.pale);box(g,3,3,0,.65,6,.72,materials.pale);box(g,0,6,0,6.65,.66,.72,materials.pale);
  box(g,0,3,-.08,5.2,5.2,.06,materials.glass);
  box(g,0,.08,0,10,.16,6,materials.stone);
  for(const [px,pz] of [[-3,0],[3,0]])cylinder(g,px,6.58,pz,.16,.16,.12,materials.gold,8);
  addCollider(x-3,z,.5);addCollider(x+3,z,.5);
  pointsOfInterest.push({x,z,r:12,name:'The Door That Opens Nowhere',line:'A doorway with no room behind it. The wind still knows how to enter.',type:'door',heard:false});
}
function makePool(x,z){
  const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);
  box(g,0,.25,0,17,.5,11,materials.pale);box(g,0,.52,0,14,.08,8,materials.blue);
  const water=new THREE.Mesh(new THREE.PlaneGeometry(13.8,7.8),new THREE.MeshPhysicalMaterial({color:'#88a9a8',roughness:.18,metalness:.18,transparent:true,opacity:.83,clearcoat:.7}));water.rotation.x=-Math.PI/2;water.position.y=.59;g.add(water);
  for(let i=0;i<4;i++){const p=box(g,-5.7+i*3.8,.72,-5,.09,.04,1.9,materials.gold);}
  for(let i=0;i<4;i++){cylinder(g,-7.2+i*4.8,2.4,-5.4,.09,.09,4.8,materials.pale,8);const lamp=new THREE.Mesh(new THREE.SphereGeometry(.22,8,8),new THREE.MeshBasicMaterial({color:'#f4dfad'}));lamp.position.set(-7.2+i*4.8,4.9,-5.4);g.add(lamp);}
  pointsOfInterest.push({x,z,r:18,name:'The Indoor Summer Pool',line:'The water has no reflection. You almost remember swimming here.',type:'pool',heard:false});
}
function makeBusStop(x,z){
  const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);
  box(g,0,2.1,0,6.2,.2,2.3,materials.dark);for(let px of [-2.7,2.7])box(g,px,1,0,.15,2,.15,materials.pale);
  box(g,0,1.12,-.94,4.8,1.6,.055,materials.glass);
  const bench=box(g,0,.7,.56,3.8,.13,.5,materials.wood);for(let px of [-1.6,1.6])box(g,px,.36,.55,.12,.7,.12,materials.dark);
  box(g,0,2.72,-.25,1.18,.38,.06,materials.blue);
  pointsOfInterest.push({x,z,r:13,name:'Last Stop, Maybe',line:'The timetable lists a departure at a time that has already passed.',type:'stop',heard:false});
}
function makeSwing(x,z){
  const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);
  for(const px of [-1.8,1.8]){const post=cylinder(g,px,2.15,0,.09,.12,4.3,materials.dark,7);post.rotation.z=px<0?-.12:.12;}
  box(g,0,4.25,0,4.1,.16,.18,materials.dark);
  for(const px of [-.65,.65]){cylinder(g,px,2.4,0,.025,.025,3.6,materials.pale,5);}
  box(g,0,.54,0,1.3,.16,.46,materials.wood);
  pointsOfInterest.push({x,z,r:11,name:'A Swing in an Empty Field',line:'It moves once, stops, then waits for someone who is not you.',type:'swing',heard:false});
}
function makeHouse(x,z){
  const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);
  box(g,0,1.7,0,7.5,3.4,6,materials.pale);
  const roof=new THREE.Mesh(new THREE.ConeGeometry(5.3,2.7,4),materials.dark);roof.rotation.y=Math.PI/4;roof.position.set(0,4.6,0);g.add(roof);
  box(g,0,1.1,-3.05,1.15,2.2,.08,materials.wood);box(g,-2.5,2,-3.08,1.1,1.15,.06,materials.glass);box(g,2.5,2,-3.08,1.1,1.15,.06,materials.glass);
  for(const px of [-2,2])box(g,px,.06,3.1,.12,.08,.2,materials.dark);
  pointsOfInterest.push({x,z,r:15,name:'The House With The Yellow Light',line:'Every room is empty. One window is warm anyway.',type:'house',heard:false});
}
function makeTallObject(x,z){
  const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);
  cylinder(g,0,4,0,.7,.85,8,materials.stone,12);
  for(let i=0;i<4;i++){const b=box(g,0,7.9-i*.5,0,3.1-i*.42,.12,3.1-i*.42,materials.pale,.3);}
  const orb=new THREE.Mesh(new THREE.SphereGeometry(.8,14,10),new THREE.MeshBasicMaterial({color:'#e4d7a8'}));orb.position.y=8.9;g.add(orb);
  pointsOfInterest.push({x,z,r:19,name:'The Listening Tower',line:'The tower is humming a note you think you know.',type:'tower',heard:false});
}
makeArch(-112,24);makePool(120,-205);makeBusStop(-190,-235);makeSwing(92,88);makeHouse(-4,-112);makeTallObject(244,-35);

// A few isolated objects in the enormous field give distance a sense of scale.
for(let i=0;i<42;i++){
  const x=rand(-380,380),z=rand(-380,380);if(Math.hypot(x,z)<35||Math.random()>.48)continue;
  const y=terrainHeight(x,z),h=rand(1.7,4.3);const pillar=cylinder(scene,x,y+h/2,z,rand(.22,.62),rand(.35,.8),h,mat(Math.random()<.5?'#91917f':'#847e6f'),6);pillar.rotation.z=rand(-.08,.08);
}

const notice=document.querySelector('#notice'), interaction=document.querySelector('#interaction'), interactionText=document.querySelector('#interaction-text');
const toast=document.querySelector('#toast');
let toastTimer;
function tell(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3200);}
let activePoint=null;
function handleInteract(){if(!started||paused)return;if(activePoint){if(!activePoint.heard){activePoint.heard=true;sanity=clamp(sanity+7,0,100);tell('KAMU MENGINGAT SESUATU');notice.textContent=activePoint.line;setTimeout(()=>{if(notice.textContent===activePoint.line)notice.textContent='';},5800);}else{tell('KAMU SUDAH PERNAH MENDENGAR INI');notice.textContent=activePoint.line;}if(audioContext)playChime();}else tell('HANYA ANGIN YANG MENJAWAB');}
function startGame(){
  if(started)return;started=true;startScreen.hidden=true;hud.hidden=false;loading.hidden=true;
  if(isTouch)mobileControls.hidden=false;
  initAudio();
  if(!isTouch&&canvas.requestPointerLock)canvas.requestPointerLock();
  tell('JANGAN TERBURU-BURU. TEMPAT INI TIDAK KE MANA-MANA.');
}
function pauseGame(){if(!started)return;paused=true;pauseScreen.hidden=false;if(document.pointerLockElement)document.exitPointerLock();}
function resumeGame(){paused=false;pauseScreen.hidden=true;if(!isTouch&&canvas.requestPointerLock)canvas.requestPointerLock();}
document.querySelector('#start-button').addEventListener('click',startGame);
document.querySelector('#resume-button').addEventListener('click',resumeGame);
document.querySelector('#restart-button').addEventListener('click',()=>location.reload());
document.querySelector('#mobile-action').addEventListener('click',handleInteract);
document.addEventListener('pointerlockchange',()=>{if(started&&!document.pointerLockElement&&!isTouch&&!paused)pauseGame();});
document.addEventListener('keydown',e=>{
  const key=e.key.toLowerCase();keys[key]=true;
  if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();
  if(key==='e')handleInteract();if(key==='escape'&&started&&!paused)pauseGame();if(key===' '&&started)jumpQueued=true;
});
document.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&!paused){yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0018,-1.35,1.35);}});
let jumpQueued=false;
const touchKeys=new Set();
document.querySelectorAll('[data-move]').forEach(button=>{
  const keymap={forward:'w',back:'s',left:'a',right:'d'},key=keymap[button.dataset.move];
  const down=e=>{e.preventDefault();keys[key]=true;};const up=e=>{e.preventDefault();keys[key]=false;};
  button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);
});
let lookTouch=null;
canvas.addEventListener('pointerdown',e=>{if(!isTouch||!started||paused)return;if(e.pointerType==='touch'){lookTouch={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);}});
canvas.addEventListener('pointermove',e=>{if(isTouch&&lookTouch&&e.pointerId===lookTouch.id){const dx=e.clientX-lookTouch.x,dy=e.clientY-lookTouch.y;yaw-=dx*.006;pitch=clamp(pitch-dy*.005,-1.35,1.35);lookTouch.x=e.clientX;lookTouch.y=e.clientY;}});
canvas.addEventListener('pointerup',e=>{if(lookTouch&&e.pointerId===lookTouch.id)lookTouch=null;});

let audioContext=null,windGain=null,windFilter=null;
function initAudio(){try{
  audioContext=new (window.AudioContext||window.webkitAudioContext)();const length=audioContext.sampleRate*3,buffer=audioContext.createBuffer(1,length,audioContext.sampleRate),data=buffer.getChannelData(0);
  for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*.52;
  const source=audioContext.createBufferSource();source.buffer=buffer;source.loop=true;windFilter=audioContext.createBiquadFilter();windFilter.type='lowpass';windFilter.frequency.value=400;windGain=audioContext.createGain();windGain.gain.value=.028;source.connect(windFilter);windFilter.connect(windGain);windGain.connect(audioContext.destination);source.start();
  const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=54;gain.gain.value=.009;osc.connect(gain);gain.connect(audioContext.destination);osc.start();
}catch(e){audioContext=null;}}
function playChime(){if(!audioContext)return;const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(392,audioContext.currentTime);osc.frequency.exponentialRampToValueAtTime(587,audioContext.currentTime+.55);gain.gain.setValueAtTime(.0001,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.035,audioContext.currentTime+.035);gain.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+1.6);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+1.7);}
let windStrength=.45;
function updateWorld(dt){
  const gust=(Math.sin(time*.13)+Math.sin(time*.071+1.7)*.7+Math.sin(time*.39)*.16)*.5;
  windStrength=clamp(.42+gust*.35,.12,1.05);grassMaterial.uniforms.uTime.value=time;grassMaterial.uniforms.uWind.value=windStrength*2.15;skyMat.uniforms.uTime.value=time;
  if(windGain)windGain.gain.setTargetAtTime(.018+windStrength*.03,audioContext.currentTime,.5);
  if(windFilter)windFilter.frequency.setTargetAtTime(260+windStrength*360,audioContext.currentTime,.8);
  const wind=document.querySelector('#wind-lines');wind.style.opacity=String(Math.max(0,(windStrength-.58)*.75));
  if(Math.random()<.028*windStrength){const line=document.createElement('span');line.style.top=`${rand(15,80)}%`;line.style.left=`${rand(-40,95)}%`;line.style.animationDuration=`${rand(1.3,2.4)}s`;wind.appendChild(line);setTimeout(()=>line.remove(),2400);}
}
function updatePlayer(dt){
  const grounded=player.position.y<=terrainHeight(player.position.x,player.position.z)+.015;
  if(grounded&&velocity.y<0)velocity.y=0;
  if(jumpQueued&&grounded){velocity.y=5.1;jumpQueued=false;}else if(jumpQueued)jumpQueued=false;
  velocity.y-=13.8*dt;
  forward.set(-Math.sin(yaw),0,-Math.cos(yaw));right.set(Math.cos(yaw),0,-Math.sin(yaw));
  move.set(0,0,0);if(keys.w||keys.arrowup)move.add(forward);if(keys.s||keys.arrowdown)move.sub(forward);if(keys.d||keys.arrowright)move.add(right);if(keys.a||keys.arrowleft)move.sub(right);
  if(move.lengthSq()>0)move.normalize();
  const sprint=!!keys.shift,speed=sprint?7.2:4.15,accel=grounded?18:6;
  velocity.x+=(move.x*speed-velocity.x)*Math.min(1,accel*dt);velocity.z+=(move.z*speed-velocity.z)*Math.min(1,accel*dt);
  if(move.lengthSq()===0){velocity.x*=Math.pow(.001,dt);velocity.z*=Math.pow(.001,dt);}
  const oldX=player.position.x,oldZ=player.position.z,nx=oldX+velocity.x*dt,nz=oldZ+velocity.z*dt;
  let blockedX=false,blockedZ=false;
  for(const c of colliders){if(Math.hypot(nx-c.x,nz-c.z)<c.r+.33){blockedX=true;blockedZ=true;break;}}
  if(!blockedX)player.position.x=nx;else velocity.x=0;if(!blockedZ)player.position.z=nz;else velocity.z=0;
  player.position.y+=velocity.y*dt;const floor=terrainHeight(player.position.x,player.position.z);if(player.position.y<floor){player.position.y=floor;velocity.y=0;}
  player.rotation.y=yaw;camera.rotation.x=pitch;
  const horizontal=Math.hypot(velocity.x,velocity.z),bobbing=grounded&&horizontal>.5?Math.sin(time*(sprint?13:9))*Math.min(horizontal/6,1)*.035:0;
  camera.position.y=mix(camera.position.y,1.65+bobbing+(sprint&&move.lengthSq()?-.045:0),Math.min(1,dt*10));
  let nearest=null,dist=Infinity;for(const p of pointsOfInterest){const d=Math.hypot(player.position.x-p.x,player.position.z-p.z);if(d<dist){dist=d;nearest=p;}}
  activePoint=dist<5.2?nearest:null;interaction.hidden=!activePoint;if(activePoint)interactionText.textContent=activePoint.heard?'Listen again':'E · '+nearest.name;
  const threat=pointsOfInterest.reduce((t,p)=>Math.max(t,1-smooth(5,48,Math.hypot(player.position.x-p.x,player.position.z-p.z))),0);
  const drain=.0025+(threat*.042)+(windStrength>.9?.012:0);sanity=clamp(sanity-drain*dt,0,100);
  if(activePoint&&activePoint.heard)sanity=clamp(sanity+dt*.002,0,100);
}

