function updateHud(dt){
  const pos=player.position,heading=((THREE.MathUtils.radToDeg(yaw)%360)+360)%360;
  document.querySelector('#heading').textContent=String(Math.round(heading)).padStart(3,'0')+'°';
  document.querySelector('#compass-arrow').style.transform=`rotate(${-yaw}rad)`;
  document.querySelector('#coordinates').textContent=`${Math.round(pos.x).toString().padStart(3,'0')} · ${Math.round(-pos.z).toString().padStart(3,'0')}`;
  document.querySelector('#sanity-number').textContent=Math.round(sanity);
  document.querySelector('#sanity-fill').style.width=`${sanity}%`;
  document.querySelector('#sanity-fill').style.background=sanity<30?'#d9b8ae':'#f4ead1';
  const captions=sanity>72?'Kamu merasa cukup nyata.':sanity>45?'Ada yang terasa sedikit berbeda.':sanity>20?'Pemandangan ini mulai mengingatmu.':'Jangan percaya pada jarak.';
  document.querySelector('#sanity-caption').textContent=captions;
  document.body.classList.toggle('sanity-low',sanity<48);document.body.classList.toggle('sanity-critical',sanity<24);
  let nearest=null,dist=Infinity;for(const p of pointsOfInterest){const d=Math.hypot(pos.x-p.x,pos.z-p.z);if(d<dist){dist=d;nearest=p;}}
  const label=dist<100?nearest.name:'The Quiet Fields';document.querySelector('#landmark-name').textContent=label;
  document.querySelector('#distance-label').textContent=dist<100?`${Math.round(dist)} meter dari sesuatu yang terasa familier.`:'Tidak ada jalan pulang. Tidak perlu ada.';
  clockTime=(clockTime+dt*.0045)%24;const hour=Math.floor(clockTime),minute=Math.floor((clockTime-hour)*60);document.querySelector('#clock').textContent=String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0');
  document.querySelector('#weather-label').textContent=windStrength>.82?'angin menguat':windStrength>.54?'angin lembut':'udara diam';document.querySelector('#weather-icon').textContent=windStrength>.82?'≋':windStrength>.54?'☁':'◌';
  fpsElapsed+=dt;fpsFrames++;if(fpsElapsed>.5){document.querySelector('#fps-counter').textContent=Math.round(fpsFrames/fpsElapsed)+' FPS';fpsElapsed=0;fpsFrames=0;}
  if(sanity<20&&Math.random()<dt*.17)camera.rotation.z=rand(-.008,.008);else camera.rotation.z=mix(camera.rotation.z,0,Math.min(dt*2,1));
}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));}
addEventListener('resize',resize);
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04);if(started&&!paused){time+=dt;updateWorld(dt);updatePlayer(dt);updateHud(dt);}renderer.render(scene,camera);}
frame();
setTimeout(()=>{loading.hidden=true;},1100);

