function makePool(x,z){const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);box(g,0,.25,0,17,.5,11,M.pale);box(g,0,.52,0,14,.08,8,M.blue);const water=new THREE.Mesh(new THREE.PlaneGeometry(13.8,7.8),new THREE.MeshPhysicalMaterial({color:'#88a9a8',roughness:.18,metalness:.18,transparent:true,opacity:.83,clearcoat:.7}));water.rotation.x=-Math.PI/2;water.position.y=.59;g.add(water);for(let i=0;i<4;i++){cylinder(g,-7.2+i*4.8,2.4,-5.4,.09,.09,4.8,M.pale,8);const lamp=new THREE.Mesh(new THREE.SphereGeometry(.22,8,8),new THREE.MeshBasicMaterial({color:'#f4dfad'}));lamp.position.set(-7.2+i*4.8,4.9,-5.4);g.add(lamp);}pointsOfInterest.push({x,z,r:18,name:'The Indoor Summer Pool',line:'The water has no reflection. You almost remember swimming here.',heard:false});}
function makeBusStop(x,z){const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);box(g,0,2.1,0,6.2,.2,2.3,M.dark);for(const px of [-2.7,2.7])box(g,px,1,0,.15,2,.15,M.pale);box(g,0,1.12,-.94,4.8,1.6,.055,M.glass);box(g,0,.7,.56,3.8,.13,.5,M.wood);for(const px of [-1.6,1.6])box(g,px,.36,.55,.12,.7,.12,M.dark);box(g,0,2.72,-.25,1.18,.38,.06,M.blue);pointsOfInterest.push({x,z,r:13,name:'Last Stop, Maybe',line:'The timetable lists a departure at a time that has already passed.',heard:false});}
function makeSwing(x,z){const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);for(const px of [-1.8,1.8]){const p=cylinder(g,px,2.15,0,.09,.12,4.3,M.dark,7);p.rotation.z=px<0?-.12:.12;}box(g,0,4.25,0,4.1,.16,.18,M.dark);for(const px of [-.65,.65])cylinder(g,px,2.4,0,.025,.025,3.6,M.pale,5);box(g,0,.54,0,1.3,.16,.46,M.wood);pointsOfInterest.push({x,z,r:11,name:'A Swing in an Empty Field',line:'It moves once, stops, then waits for someone who is not you.',heard:false});}
function makeHouse(x,z){const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);box(g,0,1.7,0,7.5,3.4,6,M.pale);const roof=new THREE.Mesh(new THREE.ConeGeometry(5.3,2.7,4),M.dark);roof.rotation.y=Math.PI/4;roof.position.set(0,4.6,0);g.add(roof);box(g,0,1.1,-3.05,1.15,2.2,.08,M.wood);box(g,-2.5,2,-3.08,1.1,1.15,.06,M.glass);box(g,2.5,2,-3.08,1.1,1.15,.06,M.glass);pointsOfInterest.push({x,z,r:15,name:'The House With The Yellow Light',line:'Every room is empty. One window is warm anyway.',heard:false});}
function makeTower(x,z){const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);cylinder(g,0,4,0,.7,.85,8,M.stone,12);for(let i=0;i<4;i++)box(g,0,7.9-i*.5,0,3.1-i*.42,.12,3.1-i*.42,M.pale,.3);const orb=new THREE.Mesh(new THREE.SphereGeometry(.8,14,10),new THREE.MeshBasicMaterial({color:'#e4d7a8'}));orb.position.y=8.9;g.add(orb);pointsOfInterest.push({x,z,r:19,name:'The Listening Tower',line:'The tower is humming a note you think you know.',heard:false});}
makeArch(-112,24);makePool(120,-205);makeBusStop(-190,-235);makeSwing(92,88);makeHouse(-4,-112);makeTower(244,-35);
for(let i=0;i<42;i++){const x=rand(-380,380),z=rand(-380,380);if(Math.hypot(x,z)<35||Math.random()>.48)continue;const y=terrainHeight(x,z),h=rand(1.7,4.3),p=cylinder(scene,x,y+h/2,z,rand(.22,.62),rand(.35,.8),h,mat(Math.random()<.5?'#91917f':'#847e6f'),6);p.rotation.z=rand(-.08,.08);}

