const $=s=>document.querySelector(s),notice=$('#notice'),interaction=$('#interaction'),interactionText=$('#interaction-text');
const audio={context:null,master:null,wind:null};
function startAudio(){if(audio.context){audio.context.resume();return;}try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audio.context=new C();audio.master=audio.context.createGain();audio.master.gain.value=.18;audio.master.connect(audio.context.destination);const buffer=audio.context.createBuffer(1,audio.context.sampleRate*3,audio.context.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const source=audio.context.createBufferSource();source.buffer=buffer;source.loop=true;const filter=audio.context.createBiquadFilter();filter.type='lowpass';filter.frequency.value=460;audio.wind=audio.context.createGain();audio.wind.gain.value=.08;source.connect(filter).connect(audio.wind).connect(audio.master);source.start();}catch(e){console.warn('Audio ambience unavailable',e);}}
function playTone(freq=440,duration=.45){if(!audio.context)return;const o=audio.context.createOscillator(),g=audio.context.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,audio.context.currentTime);g.gain.exponentialRampToValueAtTime(.12,audio.context.currentTime+.03);g.gain.exponentialRampToValueAtTime(.0001,audio.context.currentTime+duration);o.connect(g).connect(audio.master);o.start();o.stop(audio.context.currentTime+duration+.02);}
let noticeTimer=0,currentPoi=null,groundY=0,lastFootstep=0,touchLook=null;
function showNotice(text,duration=4200){notice.textContent=text;notice.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.classList.remove('visible'),duration);}
function setPaused(value){if(!started)return;paused=value;pauseScreen.hidden=!paused;hud.hidden=paused;mobileControls.hidden=paused||!isTouch;if(paused){document.exitPointerLock?.();}else{clock.getDelta();if(audio.context)audio.context.resume();}}
function begin(){if(started)return;started=true;paused=false;startScreen.hidden=true;pauseScreen.hidden=true;hud.hidden=false;mobileControls.hidden=!isTouch;loading.hidden=true;clock.start();startAudio();showNotice('Tempat ini tidak meminta apa pun darimu.',5000);if(!isTouch&&canvas.requestPointerLock)canvas.requestPointerLock();}
$('#start-button').addEventListener('click',begin);$('#resume-button').addEventListener('click',()=>setPaused(false));$('#pause-button').addEventListener('click',()=>setPaused(true));$('#restart-button').addEventListener('click',()=>{player.position.set(0,0,14);velocity.set(0,0,0);yaw=0;pitch=0;sanity=86;pointsOfInterest.forEach(p=>p.heard=false);$('#sanity-number').textContent='86';$('#sanity-fill').style.width='86%';pauseScreen.hidden=true;started=false;hud.hidden=true;mobileControls.hidden=true;startScreen.hidden=false;});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&started)setPaused(!paused);if(e.code==='KeyE'&&started&&!paused)interact();if(e.code==='Space'&&started&&!paused)jumpQueued=true;});document.addEventListener('keyup',e=>keys[e.code]=false);document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement!==canvas&&started&&!paused&&!isTouch)setPaused(true);});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&started&&!paused){yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0018,-1.35,1.35);}});
canvas.addEventListener('click',()=>{if(started&&!paused&&!isTouch&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.();});canvas.addEventListener('pointerdown',e=>{if(!isTouch||!started||paused||e.target.closest('button'))return;touchLook={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture?.(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(touchLook&&e.pointerId===touchLook.id){const dx=e.clientX-touchLook.x,dy=e.clientY-touchLook.y;yaw-=dx*.006;pitch=clamp(pitch-dy*.005,-1.35,1.35);touchLook={x:e.clientX,y:e.clientY,id:e.pointerId};}});canvas.addEventListener('pointerup',()=>touchLook=null);canvas.addEventListener('pointercancel',()=>touchLook=null);
for(const button of document.querySelectorAll('[data-move]')){const code={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[button.dataset.move];const down=e=>{e.preventDefault();keys[code]=true;button.setPointerCapture?.(e.pointerId);},up=e=>{e.preventDefault();keys[code]=false;};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up);}$('#mobile-action').addEventListener('click',interact);
